questionvariables.text:
alist: [["AG","AB","GAB","ABG",["AFG","ABC","ABG","ACG"],16,12,11],["AG","AE","GAE","AEG",["ADE","AEG","ACG","AEF"],24,8,12],["HB","BC","HBC","BCH",["BCD","BCG","BDH","BCH"],24,18,4],["CE","CD","ECD","CDE",["ACD","ACE","CDH","CDE"],17,8,11],["DF","DA","FDA","ADF",["ADE","ADF","BDF","ABD"],10,8,4],["AC","AF","CAF","ACF",["AFG","ABF","ACF","ABC"],23,17,14],["AF","AH","FAH","AFH",["ABF","AEH","AEF","AFH"],21,15,7],["CA","CH","ACH","ACH",["ACD","CDH","ACH","ACG"],15,9,6],["GB","GD","BGD","BDG",["BCG","BFG","BDG","CDG"],13,12,3],["BE","BG","EBG","BEG",["BCG","BFG","ABE","BEG"],18,9,7]];
/* Design: angle between two lines in a cuboid (angle in a triangle; cosine rule). Five right-angled cases and five cosine-rule cases. othA: the triangle's other angle that is not 90 degrees; othB: the third angle (NA in right-angled cases); cp: 90 - theta (NB in right-angled cases, where it equals othA). Source: adapted from SMP GCSE Higher 2, Chapter 34, A6 and A10. */
ix: 1+rand(10); AA: alist[ix];
L1: AA[1]; L2: AA[2]; nm: AA[3]; tri: AA[4]; OP: AA[5]; ll: AA[6]; ww: AA[7]; hh: AA[8];
LS: "ABCDEFGH"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[0,0,hh],[ll,0,hh],[ll,ww,hh],[0,ww,hh]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
XX: charat(nm,1); PV: charat(nm,2); YY: charat(nm,3);
PX: sconcat(PV,XX); PY: sconcat(PV,YY); XY: sconcat(XX,YY);
qX: sq(PX); qY: sq(PY); qXY: sq(XY);
th: angd(nm); aX: angd(sconcat(PV,XX,YY)); aY: angd(sconcat(PV,YY,XX));
rX: is(abs(aX-90) < 1/10^6); rY: is(abs(aY-90) < 1/10^6); rt: is(rX or rY);
nX: sconcat(XX,"-angle");
oA: if rX then sconcat(PV,YY,XX) else sconcat(PV,XX,YY); othA: if rX then aY else aX;
oB: sconcat(PV,YY,XX); othB: if rt then NA else aY;
cp: if rt then NB else 90-th;
RR: if rX then XX else YY; PR: sconcat(PV,RR); HY: if rX then PY else PX;
qR: sq(PR); qH: sq(HY);
oV: if rX then XX else YY;
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = tri), o], o, OP);
wr: sublist(OP, lambda([o], is(o # tri))); w1: wr[1]; w2: wr[2]; w3: wr[3];
inT(s,T) := is(ssearch(charat(s,1),T) # false and ssearch(charat(s,2),T) # false);

feedbackvariables.text:
h1: inT(L1, ans1); h2: inT(L2, ans1);
msg(s) := if ssearch(charat(s,1), ans1) = false then charat(s,1) else charat(s,2);
mA: msg(L1); mB: msg(L2);
